    for kind,name in (('GEOMETRY','Geometry'),('FLOAT','Step'),('BOOLEAN','Done'),('INT','Accepted')): end.repeat_items.new(kind,name)
    begin.pair_with_output(end);begin.inputs['Iterations'].default_value=steps;begin.inputs['Step'].default_value=.1
